// ============================================================
// CONFIG — replace placeholders, OR set as n8n env vars
// (self-hosted). On n8n Cloud, $env is blocked: edit literals.
// ============================================================
const NMI_SIGNING_KEY = 'REDACTED_nmi_key'; // from Settings > Webhooks (plain string)
const GHL_LOCATION_ID = 'pit-ab21532a-ab92-4d46-9dee-04c5a921e6ec';

const item = $input.first();
const rawHeaders = item.json.headers || {};
const h = {};
for (const k in rawHeaders) h[k.toLowerCase()] = rawHeaders[k];

// body + exact signed bytes
let bodyObj, raw;
if (typeof item.json.body === 'string') {
  raw = item.json.body;
  try { bodyObj = JSON.parse(raw); } catch (e) { bodyObj = {}; }
} else {
  bodyObj = item.json.body || {};
  raw = JSON.stringify(bodyObj);   // compact, key order preserved => matches NMI
}

// Webhook-Signature: t=<nonce>,s=<sig>
const sigHeader = h['webhook-signature'] || '';
const m = String(sigHeader).match(/t=(.*),s=(.*)/);
const nonce = m ? m[1] : '';
const providedSig = m ? m[2] : '';

const et = bodyObj.event_type ? String(bodyObj.event_type) : '';
const eb = bodyObj.event_body || {};
const b  = eb.billing_address || {};

const firstName = b.first_name || '';
const lastName  = b.last_name  || '';
const email     = (b.email || '').trim();
const phone     = (b.phone || b.cell_phone || '').trim();

// Accept ONLY sale-success events that have at least some identity
const isSaleSuccess = (et === 'transaction.sale.success');
const hasIdentity   = !!(firstName || lastName || email || phone);
const accepted      = isSaleSuccess && hasIdentity;

return [{ json: {
  // signature verification:
  signedContent: nonce + '.' + raw,
  providedSig: providedSig,
  hasSig: !!m,
  // routing:
  eventType: et || 'unknown',
  accepted: accepted,
  // contact fields:
  firstName: firstName,
  lastName:  lastName,
  email:     email,
  phone:     phone,
  country:   b.country || '',
  // NMI customer / vault reference (customer_vault_id, else customerid):
  customerVaultId: eb.customer_vault_id || eb.customerid || '',
  merchantId: (eb.merchant && eb.merchant.id) || '',
  transactionId: eb.transaction_id || '',
  amount: eb.requested_amount || '',
  source: 'NMI Sale',
  locationId: GHL_LOCATION_ID
}}];

// ============================================================
// CONFIG — replace placeholders, OR set as n8n env vars
// (self-hosted). On n8n Cloud, $env is blocked: edit literals.
// ============================================================
const NMI_SIGNING_KEY = 'REDACTED_nmi_key'; // from Settings > Webhooks (plain string)
const GHL_LOCATION_ID = 'pit-ab21532a-ab92-4d46-9dee-04c5a921e6ec';

const item = $input.first();
const rawHeaders = item.json.headers || {};
const h = {};
for (const k in rawHeaders) h[k.toLowerCase()] = rawHeaders[k];

// raw body (Webhook node has "Raw Body" enabled)
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else if (typeof item.json.body === 'string') {
  raw = item.json.body;
} else if (item.json.body !== undefined) {
  raw = JSON.stringify(item.json.body);
} else {
  raw = JSON.stringify(item.json);
}

// parse Webhook-Signature: t=<nonce>,s=<sig>
const sigHeader = h['webhook-signature'] || '';
const m = String(sigHeader).match(/t=(.*),s=(.*)/);
const nonce = m ? m[1] : '';
const providedSig = m ? m[2] : '';

let p;
try { p = JSON.parse(raw); }
catch (e) { p = (typeof item.json.body === 'object' && item.json.body) ? item.json.body : item.json; }

const et = p && p.event_type ? String(p.event_type) : '';
const eb = (p && p.event_body) ? p.event_body : {};
const b  = eb.billing_address || {};

return [{ json: {
  // for signature verification:
  signedContent: nonce + '.' + raw,
  providedSig: providedSig,
  hasSig: !!m,
  // normalized contact fields:
  firstName: b.first_name || '',
  lastName:  b.last_name  || '',
  email:    (b.email || '').trim(),
  phone:    (b.phone || b.cell_phone || '').trim(),
  company:   b.company || '',
  address1:  b.address_1 || '',
  city:      b.city || '',
  state:     b.state || '',
  postalCode: b.postal_code || '',
  country:   b.country || '',
  customerVaultId: eb.customer_vault_id || eb.token || eb.customerid || '',
  merchantId: (eb.merchant && eb.merchant.id) || '',
  eventType:  et || 'unknown',
  source:    'NMI Customer Vault',
  locationId: GHL_LOCATION_ID
}}];
